INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (1, 'Orders', 'How do I place an order?', 'Add pieces to your bag, proceed to checkout and follow the steps for contact details, delivery address and payment. You will receive a confirmation email with your order number immediately.', 0, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01', 'fashion');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (2, 'Orders', 'Can I change or cancel my order?', 'Orders can be changed or cancelled within two hours of being placed. Contact client care with your order number and we will do our best to help before the order is dispatched.', 1, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01', 'fashion');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (3, 'Orders', 'Where is my order confirmation?', 'Confirmations are sent within minutes to the email used at checkout. Please check your spam folder; if it is still missing, contact client care.', 2, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01', 'fashion');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (4, 'Shipping', 'How long does delivery take?', 'Standard delivery takes 3–5 business days across India. Express delivery arrives in 1–2 business days in metro cities. International delivery takes 5–10 business days.', 3, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01', 'fashion');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (5, 'Shipping', 'Do you offer free shipping?', 'Yes — standard delivery is complimentary on orders over ₹15,000 and express delivery is complimentary over ₹40,000.', 4, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01', 'fashion');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (6, 'Shipping', 'Do you ship internationally?', 'We ship to over 40 countries. Duties and taxes are calculated at checkout so there are no surprises on delivery.', 5, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01', 'fashion');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (7, 'Returns', 'What is your return policy?', 'You have 30 days from delivery to return any unworn piece with its tags attached for a full refund. Returns are collected from your door at no charge.', 6, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01', 'fashion');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (8, 'Returns', 'How do I start a return?', 'Sign in to your account, open the order and choose “Start a return”, or contact client care with your order number. We will arrange collection within 48 hours.', 7, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01', 'fashion');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (9, 'Exchanges', 'Can I exchange for a different size?', 'Yes. Request an exchange within 30 days and we will send the new size as soon as the original is collected — usually within 2–3 business days.', 8, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01', 'fashion');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (10, 'Exchanges', 'Can I exchange a gift?', 'Gifts can be exchanged for another size or colour, or for store credit, within 30 days of the original delivery date.', 9, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01', 'fashion');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (11, 'Payments', 'Which payment methods do you accept?', 'Visa, Mastercard, American Express, RuPay, UPI, net banking, major wallets and cash on delivery (a small handling fee applies to COD).', 10, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01', 'fashion');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (12, 'Payments', 'Is my payment information secure?', 'All payments are processed over 256-bit encrypted connections by PCI-DSS compliant partners. We never store your card details.', 11, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01', 'fashion');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (13, 'Products', 'How do I find my size?', 'Every product page links to our size guide with detailed measurements. If you are between sizes, we suggest sizing up for outerwear and down for knitwear.', 12, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01', 'fashion');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (14, 'Products', 'Are your products authentic?', 'Every piece is designed by the house and made in our partner ateliers. Each order ships with a certificate of authenticity.', 13, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01', 'fashion');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (15, 'Account', 'Do I need an account to order?', 'No — you can check out as a guest. An account lets you track orders, save addresses and keep a wishlist across devices.', 14, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01', 'fashion');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (16, 'Account', 'How do I reset my password?', 'Use “Forgot password” on the sign-in page and we will email you a secure reset link.', 15, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01', 'fashion');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (17, 'General', 'Do you have physical boutiques?', 'Yes. Our flagship is in Bengaluru with boutiques in Mumbai and New Delhi. See the store locator for hours and directions.', 16, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01', 'fashion');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (18, 'General', 'How can I contact you?', 'Email care@maisonelan.com or call +91 80 4500 1200, Monday to Saturday, 10:00–19:00 IST.', 17, 1, '2026-09-16 05:53:01', '2026-09-16 05:53:01', 'fashion');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (19, 'Orders', 'How fast will my order arrive?', '<p>Most orders arrive within 10–30 minutes of being placed. You can watch the live status on your order page.</p>', 0, 1, '2026-09-18 06:31:49', '2026-09-18 06:31:49', 'grocery');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (20, 'Orders', 'Is there a minimum order value?', '<p>No minimum. Small orders may carry a delivery charge, which is shown at checkout before you pay.</p>', 1, 1, '2026-09-18 06:31:49', '2026-09-18 06:31:49', 'grocery');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (21, 'Orders', 'Can I change or cancel an order?', '<p>Yes — until it is packed. Open the order from your account and tap Cancel. After packing, use the fresh guarantee for any issue.</p>', 2, 1, '2026-09-18 06:31:49', '2026-09-18 06:31:49', 'grocery');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (22, 'Shipping', 'Which areas do you deliver to?', '<p>Bengaluru, Mumbai, Delhi NCR, Hyderabad, Chennai, Pune, Kolkata and Ahmedabad. Enter your pincode in the header to check your locality.</p>', 3, 1, '2026-09-18 06:31:49', '2026-09-18 06:31:49', 'grocery');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (23, 'Shipping', 'What are your delivery hours?', '<p>7 am to 11 pm, all days including holidays.</p>', 4, 1, '2026-09-18 06:31:49', '2026-09-18 06:31:49', 'grocery');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (24, 'Shipping', 'Can I schedule a delivery?', '<p>Yes. Choose a delivery option at checkout and we will deliver in that window.</p>', 5, 1, '2026-09-18 06:31:49', '2026-09-18 06:31:49', 'grocery');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (25, 'Returns', 'What if an item is not fresh?', '<p>Report it from your order page within 24 hours and we will replace or refund it — no questions asked.</p>', 6, 1, '2026-09-18 06:31:49', '2026-09-18 06:31:49', 'grocery');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (26, 'Returns', 'How long do refunds take?', '<p>3–5 business days to the original payment method. Cash-on-delivery refunds go to your wallet or bank account.</p>', 7, 1, '2026-09-18 06:31:49', '2026-09-18 06:31:49', 'grocery');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (27, 'Payments', 'Which payment methods do you accept?', '<p>UPI, credit and debit cards, wallets, net banking and cash on delivery.</p>', 8, 1, '2026-09-18 06:31:49', '2026-09-18 06:31:49', 'grocery');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (28, 'Payments', 'Are prices inclusive of GST?', '<p>Yes. The bill you see at checkout is what you pay — no surprises at the door.</p>', 9, 1, '2026-09-18 06:31:49', '2026-09-18 06:31:49', 'grocery');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (29, 'Products', 'What do the green and red marks mean?', '<p>A green mark means the product is vegetarian; a red mark means it contains egg, meat or fish.</p>', 10, 1, '2026-09-18 06:31:49', '2026-09-18 06:31:49', 'grocery');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (30, 'Products', 'How do you keep produce fresh?', '<p>Fruits and vegetables arrive from farms and mandis every morning and are stored chilled at the dark store until they are packed for you.</p>', 11, 1, '2026-09-18 06:31:49', '2026-09-18 06:31:49', 'grocery');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (31, 'Account', 'Do I need an account to order?', '<p>No, you can check out as a guest. An account lets you save addresses, reorder in one tap and track every order.</p>', 12, 1, '2026-09-18 06:31:49', '2026-09-18 06:31:49', 'grocery');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (32, 'General', 'Do you offer a subscription for milk or bread?', '<p>Not yet — one-tap reorders from your account are the quickest way to restock daily essentials.</p>', 13, 1, '2026-09-18 06:31:49', '2026-09-18 06:31:49', 'grocery');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (46, 'Orders', 'How long does delivery take?', '<p>2–3 business days to metro cities and 3–5 days elsewhere. Orders placed before 2 pm ship the same day.</p>', 0, 1, '2026-09-18 07:53:07', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (47, 'Orders', 'Is there free delivery?', '<p>Yes — on all orders above ₹999. Smaller orders carry a flat charge shown at checkout.</p>', 1, 1, '2026-09-18 07:53:07', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (48, 'Orders', 'Can I order in bulk or for corporate gifting?', '<p>Yes. Write to us through the contact page with quantities and we will send a quote within one business day.</p>', 2, 1, '2026-09-18 07:53:07', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (49, 'Products', 'Are your products certified organic?', '<p>Products in the Organic Foods section are India Organic / NPOP certified. Other products are natural and minimally processed but may come from farms still in conversion.</p>', 3, 1, '2026-09-18 07:53:07', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (50, 'Products', 'Why does my honey or ghee look different from the last jar?', '<p>Natural products vary by season. Raw honey crystallises and ghee turns granular in cooler weather — both are signs of purity, not spoilage.</p>', 4, 1, '2026-09-18 07:53:07', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (51, 'Products', 'What do the dietary tags mean?', '<p>Tags such as Organic, Vegan, Gluten-free and Stone-ground describe how a product was grown or made. Use the dietary filter on any listing to shop by them.</p>', 5, 1, '2026-09-18 07:53:07', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (52, 'Products', 'How do I know the harvest date?', '<p>Every pack prints its harvest or milling date, origin and lot number. Flours are milled weekly; dry fruits are nitrogen-flushed for freshness.</p>', 6, 1, '2026-09-18 07:53:07', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (53, 'Shipping', 'Do you deliver outside India?', '<p>Not yet. We currently deliver to 19,000+ pincodes within India.</p>', 7, 1, '2026-09-18 07:53:07', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (54, 'Returns', 'What if my order arrives damaged?', '<p>Send us a photo within 7 days and we will replace or refund it in full.</p>', 8, 1, '2026-09-18 07:53:07', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (55, 'Returns', 'Can I return an opened product?', '<p>For hygiene reasons opened food cannot be returned unless it is defective. Unopened gift boxes can be returned within 7 days.</p>', 9, 1, '2026-09-18 07:53:07', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (56, 'Payments', 'Which payment methods do you accept?', '<p>UPI, credit and debit cards, net banking, wallets and cash on delivery.</p>', 10, 1, '2026-09-18 07:53:07', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (57, 'Account', 'Do I need an account?', '<p>You can check out as a guest. An account saves addresses, tracks orders and lets you reorder your pantry in one tap.</p>', 11, 1, '2026-09-18 07:53:07', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`, `template`) VALUES (58, 'General', 'Where do your products come from?', '<p>From farmer collectives in twelve Indian states — Punjab and Haryana for wheat and basmati, Kerala for spices and red rice, Karnataka for millets, Meghalaya for turmeric, the Nilgiris for honey.</p>', 12, 1, '2026-09-18 07:53:07', '2026-09-18 07:53:07', 'heritage');
