INSERT INTO `orders` (`id`, `number`, `user_id`, `status`, `email`, `phone`, `shipping_name`, `shipping_line1`, `shipping_line2`, `shipping_city`, `shipping_state`, `shipping_postal_code`, `shipping_country`, `shipping_method`, `shipping_cost`, `payment_method`, `payment_status`, `subtotal`, `discount`, `coupon_code`, `tax`, `total`, `carrier`, `tracking_number`, `estimated_delivery`, `notes`, `status_history`, `created_at`, `updated_at`) VALUES (15, 'ME-260918-2QEB', 1, 'confirmed', 'test@gmail.com', 'test', 'test', '12', NULL, 'test', 'test', '143001', 'India', 'Collect in boutique', 99, 'cod', 'cod', 329, 0, NULL, 0, 428, NULL, NULL, '2026-09-23 07:51:29', NULL, '[{"status":"confirmed","at":"2026-09-18T07:51:29+00:00","note":"Order placed"}]', '2026-09-18 07:51:29', '2026-09-18 07:51:29');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (1, 'Designed with intention. Made to last.', 'about', 'about', 'Our story', 'Maison Élan began with a simple question: what would a wardrobe look like if every piece earned its place?', NULL, 'https://images.unsplash.com/photo-1534126511673-b6899657816a?w=2000&q=80&auto=format&fit=crop&h=1200', 1, 'About Maison Élan — Our Story', 'The story, philosophy and craftsmanship behind Maison Élan — clothing, fragrance, timepieces and leather goods designed with intention.', NULL, NULL, 0, '2026-09-16 04:51:11', '2026-09-16 06:33:58', '{"sections":[{"layout":"text-image","eyebrow":"Brand story","heading":"Founded in a small atelier, with a *large* idea.","body":"Maison \\u00c9lan was founded in 2018 in a converted textile mill in Bengaluru by two friends \\u2014 a pattern cutter and a perfumer \\u2014 who shared a frustration with fashion that was loud, fast and forgettable.\\n\\nThe first collection was twelve pieces. Each was revised until nothing could be removed. That discipline still shapes everything the house makes.","image":"https:\\/\\/images.unsplash.com\\/photo-1571513722275-4b41940f54b8?w=1400&q=80&auto=format&fit=crop&h=1750"},{"layout":"image-text","eyebrow":"Our philosophy","heading":"Quiet confidence over *noise*.","body":"We believe the most luxurious thing a garment can do is disappear \\u2014 to feel so right that you stop thinking about it. So we obsess over proportion, weight and the way cloth moves, and we leave the logos off.\\n\\nEvery season we add a few pieces and retire almost none. A wardrobe should compound, not churn.","image":"https:\\/\\/images.unsplash.com\\/photo-1526413232644-8a40f03cc03b?w=1400&q=80&auto=format&fit=crop&h=1750"},{"layout":"text-image","eyebrow":"Craftsmanship","heading":"Three ateliers. Hundreds of hands.","body":"Tailoring is cut and sewn in our Bengaluru atelier. Leather goods are made in a family workshop in Chennai that has tanned vegetable leather for four generations. Fragrances are composed with master perfumers in Grasse.\\n\\nWe visit every partner, every year. If we would not be proud to show you the workshop, we do not work with it.","image":"https:\\/\\/images.unsplash.com\\/photo-1534126511673-b6899657816a?w=1400&q=80&auto=format&fit=crop&h=1750"}],"values":[{"title":"Material first","text":"Natural fibres, full-grain leathers and Swiss movements \\u2014 chosen for how they age, not how they photograph."},{"title":"Made in small runs","text":"We produce close to demand so nothing is discounted into landfill."},{"title":"Repair, always","text":"Every piece can be returned to us for repair for as long as you own it."},{"title":"Honest pricing","text":"No inflated list prices, no permanent sales. One fair price, all year."}],"sustainability_heading":"Responsible by design, not by press release.","sustainability_body":"Eighty percent of our fabrics are natural and certified. Our leather is vegetable-tanned without chromium. Packaging is FSC card and cotton, and our boutiques run on renewable energy.\\n\\nWe publish a short impact note every year. It is written by us, not an agency, and it includes the things we have not solved yet.","sustainability_image":"https:\\/\\/images.unsplash.com\\/photo-1558769132-cb1aea458c5e?w=1400&q=80&auto=format&fit=crop&h=1750","founder_quote":"We wanted to make the pieces people reach for without thinking \\u2014 and keep reaching for, for years.","founder_name":"Aanya Mehra & Julien Roche, founders"}', 'fashion');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (2, 'Shipping Information', 'shipping', 'legal', NULL, 'How and when your order arrives.', '<h3>Shipping methods</h3>\n<ul>\n<li><strong>Standard delivery</strong> — ₹250, complimentary over ₹15,000. Tracked courier, 3–5 business days.</li>\n<li><strong>Express delivery</strong> — ₹650, complimentary over ₹40,000. 1–2 business days to metro cities.</li>\n<li><strong>Collect in boutique</strong> — complimentary. Ready within 24 hours at Bengaluru, Mumbai or New Delhi.</li>\n</ul>\n<h3>Delivery timelines</h3>\n<p>Orders placed before 14:00 IST on a business day are dispatched the same day. Timelines are counted from dispatch and exclude Sundays and public holidays. Pre-order and made-to-measure pieces show their own estimated date on the product page.</p>\n<h3>Shipping charges</h3>\n<p>Charges are shown at checkout before you pay. There are no additional handling fees except a ₹99 fee for cash on delivery.</p>\n<h3>International shipping</h3>\n<p>We ship to over 40 countries with DHL Express in 5–10 business days. Duties and taxes are calculated and collected at checkout so nothing is due on delivery. Fragrances cannot be shipped to some destinations by air; checkout will let you know.</p>\n<h3>Order processing</h3>\n<p>You will receive a confirmation email when your order is placed and a second email with tracking when it is dispatched. Every piece is inspected, folded in tissue and packed in our ivory box.</p>\n<h3>Tracking</h3>\n<p>Use the tracking link in your dispatch email, sign in to your account, or visit <a href="/track-order">Track your order</a> with your order number and email.</p>\n<h3>Delays</h3>\n<p>Weather, customs or courier issues can occasionally delay delivery. If your order is more than three business days past its estimate, contact client care and we will investigate and, where appropriate, refund shipping.</p>\n<h3>Address changes</h3>\n<p>Addresses can be changed until the order is dispatched. Contact client care as soon as possible with your order number.</p>\n<h3>Lost or damaged packages</h3>\n<p>If your package arrives damaged, photograph the box and contents and contact us within 48 hours. If a tracked package is confirmed lost by the courier, we will replace it or refund you in full.</p>', NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-16 04:51:11', '2026-09-16 05:53:02', NULL, 'fashion');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (3, 'Returns & Exchanges', 'returns', 'legal', NULL, '30 days, collected from your door, no charge.', '<h3>Return eligibility</h3>\n<p>Any piece may be returned within 30 days of delivery provided it is unworn, unwashed, with all tags and packaging intact. Footwear must be tried on indoors and returned in its box.</p>\n<h3>Return window</h3>\n<p>30 days from the date of delivery. Gifts may be returned for store credit within 30 days of the original delivery date.</p>\n<h3>Exchange policy</h3>\n<p>Exchanges for another size or colour are complimentary. Request an exchange from your order page; the replacement is dispatched as soon as the original is collected.</p>\n<h3>Refund process and timelines</h3>\n<p>Once your return reaches our warehouse it is inspected within two business days. Refunds are issued to the original payment method and typically appear within 5–7 business days depending on your bank. Cash on delivery orders are refunded by bank transfer.</p>\n<h3>Non-returnable products</h3>\n<ul>\n<li>Fragrances that have been opened or unsealed</li>\n<li>Earrings, for hygiene reasons</li>\n<li>Gift cards</li>\n<li>Pieces altered or personalised at your request</li>\n</ul>\n<h3>Damaged or incorrect products</h3>\n<p>If anything arrives damaged or is not what you ordered, contact client care within 48 hours with photographs. We will collect the item and send a replacement or full refund, including any shipping paid.</p>\n<h3>Return shipping</h3>\n<p>Returns within India are collected from your address at no charge. International returns are sent with the prepaid label included in your parcel; the original shipping fee is not refunded.</p>\n<h3>How to initiate a return</h3>\n<ol>\n<li>Sign in and open the order under <a href="/account/orders">My orders</a>, or contact client care with your order number.</li>\n<li>Choose the items and reason. We will confirm a collection slot within 48 hours.</li>\n<li>Pack the pieces in the original packaging with the tags attached.</li>\n<li>Hand the parcel to the courier and keep the receipt until your refund is confirmed.</li>\n</ol>', NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-16 04:51:11', '2026-09-16 05:53:02', '{"cta_label":"Start a return","cta_url":"\\/account\\/orders"}', 'fashion');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (4, 'Privacy Policy', 'privacy', 'legal', NULL, NULL, '<p>This policy explains what personal information Maison Élan collects, how we use it and the choices you have. It applies to our website, boutiques and client care.</p>\n<h3>Information we collect</h3>\n<p>Contact details (name, email, phone, addresses), order and payment information, account credentials, your communications with us, and technical data such as device, browser and pages visited.</p>\n<h3>How we use it</h3>\n<p>To fulfil and deliver orders, provide client care, personalise your experience, prevent fraud, improve the website and — with your consent — send marketing communications.</p>\n<h3>Cookies</h3>\n<p>We use essential cookies to run the site and, with your permission, analytics and marketing cookies. See our <a href="/cookies">Cookie Policy</a> for details and controls.</p>\n<h3>Analytics</h3>\n<p>Aggregated, anonymised analytics help us understand how the site is used. Analytics cookies are only set if you accept them.</p>\n<h3>Payment information</h3>\n<p>Payments are processed by PCI-DSS certified providers. We receive confirmation of payment and the last four digits of your card; we never store full card numbers.</p>\n<h3>Third-party services</h3>\n<p>We share data only with providers who help us operate: couriers, payment processors, email services and analytics. Each is bound by contract to protect your data and use it only for our instructions.</p>\n<h3>Marketing communications</h3>\n<p>You will receive marketing emails only if you subscribe. Every email includes an unsubscribe link, and you can change preferences in your account at any time.</p>\n<h3>Data security</h3>\n<p>Data is encrypted in transit and at rest, access is limited to staff who need it, and we review our safeguards regularly.</p>\n<h3>Your rights</h3>\n<p>You may request access to, correction of, or deletion of your data, object to processing, or ask for a portable copy. Email <a href="mailto:care@maisonelan.com">care@maisonelan.com</a> and we will respond within 30 days.</p>\n<h3>Data retention</h3>\n<p>Order records are kept for seven years to meet tax and legal obligations. Account data is kept while your account is active and deleted on request.</p>\n<h3>Contact</h3>\n<p>Maison Élan Private Limited, 12 Lavelle Road, Bengaluru 560001, India · <a href="mailto:care@maisonelan.com">care@maisonelan.com</a></p>', NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-16 04:51:11', '2026-09-16 05:53:02', NULL, 'fashion');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (5, 'Terms & Conditions', 'terms', 'legal', NULL, NULL, '<p>By using this website you agree to these terms. Please read them carefully.</p>\n<h3>Website usage</h3>\n<p>You may use the site for personal, non-commercial purposes. You must not misuse it, attempt to gain unauthorised access, or use automated tools to scrape content.</p>\n<h3>Account registration</h3>\n<p>You are responsible for keeping your credentials confidential and for all activity under your account. Please tell us immediately if you suspect unauthorised use.</p>\n<h3>Product information</h3>\n<p>We take care to describe products accurately. Minor variations in colour and natural materials are not defects. Product availability is not guaranteed until an order is confirmed.</p>\n<h3>Pricing</h3>\n<p>Prices are in Indian Rupees and include GST unless stated. We may change prices at any time; the price shown at checkout is the price you pay. Obvious pricing errors may be corrected and affected orders cancelled with a full refund.</p>\n<h3>Orders</h3>\n<p>Your order is an offer to purchase. A contract is formed when we dispatch the goods. We may refuse or cancel orders for reasons including suspected fraud, stock errors or address problems.</p>\n<h3>Payments</h3>\n<p>Payment is taken when the order is placed. You confirm that you are authorised to use the payment method provided.</p>\n<h3>Intellectual property</h3>\n<p>All content — designs, photography, text, logos — belongs to Maison Élan or its licensors and may not be reproduced without written permission.</p>\n<h3>User content</h3>\n<p>By submitting reviews or messages you grant us a non-exclusive licence to use them. Content must be honest, lawful and respectful; we may remove content that is not.</p>\n<h3>Limitation of liability</h3>\n<p>To the extent permitted by law, our liability for any claim relating to an order is limited to the amount paid for that order. Nothing limits liability for death, personal injury or fraud.</p>\n<h3>Governing law</h3>\n<p>These terms are governed by the laws of India. Disputes are subject to the exclusive jurisdiction of the courts of Bengaluru.</p>\n<h3>Contact</h3>\n<p>Maison Élan Private Limited, 12 Lavelle Road, Bengaluru 560001 · <a href="mailto:care@maisonelan.com">care@maisonelan.com</a></p>', NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-16 04:51:11', '2026-09-16 05:53:02', NULL, 'fashion');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (6, 'Cookie Policy', 'cookies', 'cookies', NULL, 'What cookies we use, why, and how to control them.', '<h3>What cookies are</h3>\n<p>Cookies are small text files stored on your device by your browser. They let a website remember your choices, keep you signed in and understand how the site is used.</p>\n<h3>Essential cookies</h3>\n<p>Required for the site to work: your session, shopping bag, sign-in state and security tokens. These cannot be switched off.</p>\n<h3>Analytics cookies</h3>\n<p>Help us understand which pages are used and where the site could be improved. Data is aggregated and anonymised. Set only with your consent.</p>\n<h3>Marketing cookies</h3>\n<p>Used to measure campaigns and show relevant content on other platforms. Set only with your consent.</p>\n<h3>Third-party cookies</h3>\n<p>Some cookies are set by partners such as analytics and payment providers. We only work with partners who meet our privacy standards.</p>\n<h3>Cookie preferences</h3>\n<p>Use the controls below to change your preferences at any time. You can also delete cookies through your browser settings.</p>', NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-16 04:51:11', '2026-09-16 05:53:02', NULL, 'fashion');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (7, 'Accessibility Statement', 'accessibility', 'legal', NULL, NULL, '<p>Maison Élan is committed to making our website usable by everyone, regardless of ability or technology. We aim to conform to WCAG 2.2 Level AA.</p><h3>What we do</h3><ul><li>Semantic HTML, keyboard-navigable menus, drawers and forms</li><li>Visible focus states and a “skip to content” link</li><li>Alternative text for product and campaign imagery</li><li>Colour contrast that meets AA on all text</li><li>Reduced-motion support: animations are disabled when your system requests it</li></ul><h3>Feedback</h3><p>If you encounter a barrier, please email <a href="mailto:care@maisonelan.com">care@maisonelan.com</a> with the page address and a description. We respond within two business days and prioritise fixes.</p>', NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-16 04:51:11', '2026-09-16 05:53:02', NULL, 'fashion');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (8, 'Disclaimer', 'disclaimer', 'legal', NULL, NULL, '<p>The information on this website is provided in good faith and for general information only. While we make every effort to keep product descriptions, pricing and availability accurate, errors may occur. We reserve the right to correct any error and to cancel orders affected by it, with a full refund.</p><p>Colours may vary slightly from those shown on screen depending on your device. Natural materials such as leather and wool have inherent variations that are part of their character, not defects.</p><p>External links are provided for convenience; we are not responsible for the content of third-party sites.</p>', NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-16 04:51:11', '2026-09-16 05:53:02', NULL, 'fashion');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (9, 'Size Guide', 'size-guide', 'size-guide', 'Fit', 'Measurements in centimetres. If you are between sizes, size up for outerwear and down for knitwear.', NULL, NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-16 04:51:11', '2026-09-16 05:53:02', '{"tables":[{"name":"Womenswear","columns":["Size","Bust","Waist","Hips"],"rows":[["XS","80\\u201384","62\\u201366","88\\u201392"],["S","84\\u201388","66\\u201370","92\\u201396"],["M","88\\u201392","70\\u201374","96\\u2013100"],["L","92\\u201397","74\\u201379","100\\u2013105"],["XL","97\\u2013102","79\\u201384","105\\u2013110"]]},{"name":"Menswear","columns":["Size","Chest","Waist","Shoulder"],"rows":[["S","92\\u201396","78\\u201382","44"],["M","96\\u2013100","82\\u201386","46"],["L","100\\u2013104","86\\u201390","48"],["XL","104\\u2013108","90\\u201394","50"],["XXL","108\\u2013112","94\\u201398","52"]]},{"name":"Belts","columns":["Size","Waist (cm)","Waist (in)"],"rows":[["80","76\\u201380","30\\u201331"],["85","81\\u201385","32\\u201333"],["90","86\\u201390","34\\u201335"],["95","91\\u201395","36\\u201337"],["100","96\\u2013100","38\\u201339"]]},{"name":"Footwear","columns":["EU","UK","US","Foot length (cm)"],"rows":[["40","6","7","25.4"],["41","7","8","26.0"],["42","8","9","26.7"],["43","9","10","27.3"],["44","10","11","28.0"],["45","11","12","28.6"]]}],"how_to":[{"title":"Bust \\/ Chest","text":"Measure around the fullest part, keeping the tape level and relaxed."},{"title":"Waist","text":"Measure around the narrowest part of your natural waistline."},{"title":"Hips","text":"Stand with feet together and measure around the fullest part."},{"title":"Shoulder","text":"Measure from shoulder seam to shoulder seam across the back."}]}', 'fashion');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (10, 'Care Guide', 'care-guide', 'care-guide', 'Longevity', 'Pieces made to last deserve to be looked after. A few habits make the difference between years and decades.', NULL, NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-16 04:51:11', '2026-09-16 05:53:02', '{"materials":[{"name":"Wool & cashmere","image":"https:\\/\\/images.unsplash.com\\/photo-1539533018447-63fcce2678e3?w=900&q=80&auto=format&fit=crop&h=1100","tips":["Air after wearing; wash rarely and by hand in cool water","Dry flat away from direct heat","Store folded with cedar; never hang knitwear","Remove pilling gently with a comb"]},{"name":"Leather","image":"https:\\/\\/images.unsplash.com\\/photo-1521223890158-f9f7c3d5d504?w=900&q=80&auto=format&fit=crop&h=1100","tips":["Condition every few months with a neutral balm","Keep away from prolonged sun and heat","Stuff bags with tissue and store in the dust bag","Let wet leather dry naturally, never on a radiator"]},{"name":"Cotton & linen","image":"https:\\/\\/images.unsplash.com\\/photo-1558769132-cb1aea458c5e?w=900&q=80&auto=format&fit=crop&h=1100","tips":["Machine wash cool with like colours","Line dry; tumble drying shortens fibre life","Iron while slightly damp for a crisp finish"]},{"name":"Watches","image":"https:\\/\\/images.unsplash.com\\/photo-1619134778706-7015533a6150?w=900&q=80&auto=format&fit=crop&h=1100","tips":["Wipe the case and bracelet with a soft cloth","Have automatics serviced every 4\\u20135 years","Avoid magnets and sudden temperature changes","Do not operate the crown under water"]},{"name":"Fragrance","image":"https:\\/\\/images.unsplash.com\\/photo-1622618991746-fe6004db3a47?w=900&q=80&auto=format&fit=crop&h=1100","tips":["Store in a cool, dark place \\u2014 not the bathroom","Keep the cap on to slow oxidation","Apply to pulse points; do not rub"]},{"name":"Jewellery","image":"https:\\/\\/images.unsplash.com\\/photo-1602173574767-37ac01994b2a?w=900&q=80&auto=format&fit=crop&h=1100","tips":["Put on last, take off first","Polish with the supplied cloth","Store pieces separately to prevent scratching","Keep pearls away from perfume and hairspray"]}]}', 'fashion');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (11, 'The gift of choosing.', 'gift-cards', 'gift-cards', 'Gift cards', 'Delivered by email within the hour, redeemable on every piece in the house, and never expiring.', NULL, 'https://images.unsplash.com/photo-1617038220319-276d3cfab638?w=1600&q=80&auto=format&fit=crop&h=1000', 1, NULL, NULL, NULL, NULL, 0, '2026-09-16 04:51:11', '2026-09-16 05:53:02', '{"steps":[{"title":"Choose a value","text":"From \\u20b92,500 to \\u20b925,000, or add several to your bag."},{"title":"Add a note","text":"Tell us who it is for and what to say. We will design the card around it."},{"title":"Sent within the hour","text":"Delivered by email to you or straight to the recipient, on the day you choose."}]}', 'fashion');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (12, 'Work with us.', 'careers', 'careers', 'Careers', 'We are a small team of makers, thinkers and hosts. If you care about doing fewer things exceptionally well, we would like to meet you.', NULL, 'https://images.unsplash.com/photo-1534126511673-b6899657816a?w=1600&q=80&auto=format&fit=crop&h=1000', 1, NULL, NULL, NULL, NULL, 0, '2026-09-16 04:51:11', '2026-09-16 06:33:58', '{"roles":[{"title":"Senior Pattern Cutter","location":"Bengaluru atelier","type":"Full-time","summary":"Lead the development of tailoring blocks and work directly with the design team from toile to production."},{"title":"Client Advisor","location":"Mumbai boutique","type":"Full-time","summary":"Host clients in the boutique, build lasting relationships and represent the house with warmth and knowledge."},{"title":"E-commerce Merchandiser","location":"Bengaluru \\/ hybrid","type":"Full-time","summary":"Own the storefront: product data, editorial placement, and the numbers behind what we show and when."},{"title":"Leather Craftsperson","location":"Chennai workshop","type":"Full-time","summary":"Cut, skive and stitch small leather goods to the house standard alongside our partner atelier."}],"perks":["Wardrobe allowance on every collection","Annual atelier residency","Health cover for you and family","Hybrid working for office roles"]}', 'fashion');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (13, 'Visit us.', 'stores', 'stores', 'Boutiques', 'Three boutiques, each with fitting rooms, a fragrance bar and client advisors who know the collection inside out.', NULL, NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-16 04:51:11', '2026-09-16 05:53:02', NULL, 'fashion');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (14, 'Payment Information', 'payment', 'legal', NULL, 'Accepted methods, security and billing.', '<h3>Accepted methods</h3><ul><li>Credit and debit cards: Visa, Mastercard, American Express, RuPay</li><li>UPI (Google Pay, PhonePe, Paytm and any UPI app)</li><li>Net banking from all major Indian banks</li><li>Wallets: Paytm, Amazon Pay, PhonePe</li><li>Cash on delivery within India (₹99 handling fee)</li></ul><h3>Security</h3><p>Payments are processed over encrypted connections by PCI-DSS Level 1 certified partners. We never see or store your full card number.</p><h3>Billing</h3><p>Your card is charged when the order is placed. If an item cannot be fulfilled we refund it immediately to the original payment method; refunds appear within 5–7 business days depending on your bank.</p><h3>Pricing</h3><p>All prices are in Indian Rupees and include GST. International orders show duties and taxes at checkout so there is nothing to pay on delivery.</p>', NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-16 04:51:11', '2026-09-16 05:53:02', NULL, 'fashion');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (15, 'Frequently asked questions', 'faq', 'faq', 'Help', 'Everything you need to know about ordering, delivery, returns and caring for your pieces.', NULL, NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-16 04:51:12', '2026-09-16 05:53:02', NULL, 'fashion');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (16, 'We are here to help.', 'contact', 'contact', 'Contact', 'Questions about an order, a fitting, or a gift? Our client care team replies within one business day.', NULL, NULL, 1, NULL, 'Contact Maison Élan client care by email, phone or the form below. Monday to Saturday, 10:00–19:00 IST.', NULL, NULL, 0, '2026-09-16 05:53:02', '2026-09-16 05:53:02', '{"subjects":["Order enquiry","Returns & exchanges","Product question","Sizing advice","Press","Other"]}', 'fashion');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (17, 'Fresh, fast and fairly priced.', 'about', 'about', 'About us', 'We started with one dark store and a promise: groceries as fresh as the market, delivered faster than you can find your car keys.', NULL, 'https://images.unsplash.com/photo-1542838132-92c53300491e?w=2000&q=80&auto=format&fit=crop&h=900', 1, 'About us — fresh groceries delivered in minutes', 'Who we are, how our dark stores work, and why our produce is fresher than the supermarket.', NULL, NULL, 0, '2026-09-18 06:31:49', '2026-09-18 06:31:49', '{"sections":[{"layout":"text-image","eyebrow":"How it works","heading":"Neighbourhood dark stores, not warehouses","body":"<p>Every order is packed at a small store within a few kilometres of your home. That is how we deliver in 10\\u201330 minutes without a single item spending days in transit.<\\/p>","image":"https:\\/\\/images.unsplash.com\\/photo-1604719312566-8912e9227c6a?w=1200&q=80&auto=format&fit=crop&h=900"},{"layout":"image-text","eyebrow":"Freshness","heading":"From the farm at 4 am, at your door by breakfast","body":"<p>Fruits and vegetables come straight from partner farmers and mandis every morning. Anything that does not pass our quality check goes to our food-bank partners, never to your basket.<\\/p>","image":"https:\\/\\/images.unsplash.com\\/photo-1488459716781-31db52582fe9?w=1200&q=80&auto=format&fit=crop&h=900"},{"layout":"text-image","eyebrow":"Pricing","heading":"Everyday low prices, no membership fees","body":"<p>We buy in bulk, waste less and pass the savings on. Compare us with your local kirana \\u2014 and tell us if we are ever more expensive.<\\/p>","image":"https:\\/\\/images.unsplash.com\\/photo-1583258292688-d0213dc5a3a8?w=1200&q=80&auto=format&fit=crop&h=900"}],"values":[{"title":"Fresh guarantee","text":"Not fresh? Report it within 24 hours for a replacement or refund."},{"title":"Honest weights","text":"Every pack is weighed at the store \\u2014 you get what you pay for."},{"title":"Fair to partners","text":"Delivery partners are paid per hour, not per rush."},{"title":"Less waste","text":"Reusable crates, paper bags and same-day donations of surplus food."}],"sustainability_heading":"Greener groceries, one delivery at a time.","sustainability_body":"<p>Electric two-wheelers on 70% of routes, no single-use plastic bags, and a zero-food-waste target for every dark store by next year.<\\/p>","sustainability_image":"https:\\/\\/images.unsplash.com\\/photo-1573246123716-6b1782bfc499?w=1200&q=80&auto=format&fit=crop&h=900","founder_quote":"We wanted the corner shop feeling \\u2014 someone who knows what you need \\u2014 with the convenience of an app.","founder_name":"Rohit Sharma, founder"}', 'grocery');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (18, 'How can we help?', 'contact', 'contact', 'Contact', 'Order issues, missing items or refunds — we reply within a few hours, every day of the week.', NULL, NULL, 1, NULL, 'Contact customer support by phone, WhatsApp, email or the form below.', NULL, NULL, 0, '2026-09-18 06:31:49', '2026-09-18 06:31:49', '{"subjects":["Order issue","Missing or damaged item","Refund","Product question","Delivery area request","Other"]}', 'grocery');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (19, 'Frequently asked questions', 'faq', 'faq', 'Help', 'Delivery times, freshness, payments, returns and your account — answered.', NULL, NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:31:49', '2026-09-18 06:31:49', NULL, 'grocery');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (20, 'Delivery areas & timings', 'shipping', 'legal', NULL, 'Where we deliver, how fast, and what it costs.', '<h3>Delivery areas</h3><p>We currently deliver in Bengaluru, Mumbai, Delhi NCR, Hyderabad, Chennai, Pune, Kolkata and Ahmedabad. Enter your pincode in the header to check your locality.</p><h3>Timings</h3><p>Orders are delivered from 7 am to 11 pm, all days. Most orders arrive within 10–30 minutes; during heavy rain or peak hours it may take up to 60 minutes.</p><h3>Charges</h3><p>Delivery charges depend on your order value and are shown at checkout before you pay. Orders above the free-delivery threshold are delivered free.</p><h3>Scheduled delivery</h3><p>Prefer a slot? Choose a delivery option at checkout and we will bring your order in that window.</p>', NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:31:49', '2026-09-18 06:31:49', NULL, 'grocery');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (21, 'Returns & refunds', 'returns', 'legal', NULL, 'Our fresh guarantee and how refunds work.', '<h3>Fresh guarantee</h3><p>If any item is stale, damaged, expired or not what you ordered, report it from your order page within 24 hours of delivery. We will replace it or refund it — no questions asked.</p><h3>What can be returned</h3><p>Packaged goods in original condition can be returned at the door or reported within 24 hours. For hygiene reasons, opened dairy, meat, frozen items and personal-care products cannot be returned unless defective.</p><h3>Refunds</h3><p>Refunds go back to the original payment method within 3–5 business days. Cash-on-delivery refunds are credited to your wallet or bank account.</p><h3>Missing items</h3><p>If something on your bill is missing from the bag, report it and we will refund it immediately.</p>', NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:31:49', '2026-09-18 06:31:49', NULL, 'grocery');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (22, 'Privacy policy', 'privacy', 'legal', NULL, NULL, '<h3>What we collect</h3><p>Your name, phone number, email, delivery addresses, order history and — with permission — your device location to show delivery availability.</p><h3>How we use it</h3><p>To deliver your orders, contact you about them, personalise offers and improve the service. We never sell your data.</p><h3>Sharing</h3><p>Delivery partners see only your name, address and phone number for the order they carry. Payment details are processed by PCI-DSS certified gateways and never stored by us.</p><h3>Your rights</h3><p>You can view, correct or delete your data from your account or by contacting support. We keep order records for as long as the law requires.</p>', NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:31:49', '2026-09-18 06:31:49', NULL, 'grocery');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (23, 'Terms & conditions', 'terms', 'legal', NULL, NULL, '<h3>Orders</h3><p>An order is confirmed when you receive the confirmation screen and email. Prices and availability can change; we will refund any item we cannot fulfil.</p><h3>Quantities</h3><p>Some items have a maximum quantity per order to keep stock available for every household.</p><h3>Delivery</h3><p>Someone must be available to receive the order at the address given. If nobody answers, our partner will try to contact you before returning the order.</p><h3>Cancellations</h3><p>Orders can be cancelled until they are packed. After that, use the fresh guarantee for any issue with the delivered items.</p><h3>Account</h3><p>You are responsible for keeping your login details safe. We may suspend accounts that abuse offers or refund policies.</p>', NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:31:49', '2026-09-18 06:31:49', NULL, 'grocery');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (24, 'Cookie policy', 'cookies', 'cookies', NULL, 'What cookies we use and how to control them.', '<h3>Essential</h3><p>Keep your cart, login session and delivery location. The site cannot work without them.</p><h3>Analytics</h3><p>Help us understand which products and pages are useful. Anonymous and optional.</p><h3>Marketing</h3><p>Show you relevant offers. Optional — control them from the panel on this page.</p>', NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:31:49', '2026-09-18 09:48:13', NULL, 'grocery');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (25, 'Payment options', 'payment', 'legal', NULL, 'Accepted methods and security.', '<h3>Accepted methods</h3><ul><li>UPI — Google Pay, PhonePe, Paytm and every UPI app</li><li>Credit and debit cards — Visa, Mastercard, RuPay</li><li>Wallets — Paytm, Amazon Pay</li><li>Net banking</li><li>Cash on delivery (pay by cash or UPI at the door)</li></ul><h3>Security</h3><p>Payments are processed by PCI-DSS Level 1 certified partners over encrypted connections. We never see or store your card number.</p><h3>Pricing</h3><p>All prices are in Indian rupees and include GST. The bill you see at checkout is the bill you pay.</p>', NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:31:49', '2026-09-18 06:31:49', NULL, 'grocery');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (26, 'Gift groceries, not guesses.', 'gift-cards', 'gift-cards', 'Gift cards', 'Send a grocery gift card to family, friends or house-help — delivered by email in minutes, valid for a year.', NULL, 'https://images.unsplash.com/photo-1608686207856-001b95cf60ca?w=1600&q=80&auto=format&fit=crop&h=800', 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:31:49', '2026-09-18 06:31:49', '{"steps":[{"title":"Pick an amount","text":"From \\u20b9250 to \\u20b95,000."},{"title":"Add a message","text":"We email the card with your note."},{"title":"They shop","text":"Redeemable on every product at checkout."}]}', 'grocery');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (27, 'Join the team.', 'careers', 'careers', 'Careers', 'Store partners, riders, category managers and engineers — we are hiring across every city we deliver in.', NULL, 'https://images.unsplash.com/photo-1556910103-1c02745aae4d?w=1600&q=80&auto=format&fit=crop&h=800', 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:31:49', '2026-09-18 06:31:49', '{"roles":[{"title":"Dark Store Manager","location":"Bengaluru","type":"Full-time","summary":"Run a neighbourhood store: stock, freshness checks, packing speed and a small team of partners."},{"title":"Delivery Partner","location":"All cities","type":"Flexible","summary":"Deliver within a few kilometres on an e-scooter. Hourly pay, fuel included, weekly payouts."},{"title":"Category Manager \\u2014 Fresh","location":"Mumbai","type":"Full-time","summary":"Source fruits and vegetables from farmers and mandis; own quality, pricing and waste."},{"title":"Backend Engineer","location":"Remote (India)","type":"Full-time","summary":"Build the ordering, routing and inventory systems behind 10-minute delivery."}],"perks":["Free groceries allowance every month","Health insurance for you and family","Hourly pay for partners, never per-order pressure","Fast growth into store and city roles"]}', 'grocery');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (28, 'Our stores', 'stores', 'stores', 'Locations', 'Walk in, pick up an order, or return an item at any of our neighbourhood stores.', NULL, NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:31:49', '2026-09-18 06:31:49', NULL, 'grocery');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (29, 'Grown by farmers we know.', 'about', 'about', 'Our story', 'We started in 2016 with three farmer families in Punjab and one promise: staples the way they were before industrial milling — clean, traceable and honest.', NULL, 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?w=2000&q=80&auto=format&fit=crop&h=900', 1, 'Our story — single-origin Indian staples', 'How we work with farmer collectives across twelve states to bring stone-ground, cold-pressed, sun-dried Indian staples to your kitchen.', NULL, NULL, 0, '2026-09-18 06:49:45', '2026-09-18 06:49:45', '{"sections":[{"layout":"text-image","eyebrow":"Sourcing","heading":"Twelve states, 1,200 farmers, one standard","body":"<p>Every product is traced to a farmer collective. We visit at harvest, agree prices above the mandi rate before sowing, and test each lot in an FSSAI-approved laboratory for pesticide residue and adulteration.<\\/p>","image":"https:\\/\\/images.unsplash.com\\/photo-1464226184884-fa280b87c399?w=1200&q=80&auto=format&fit=crop&h=900"},{"layout":"image-text","eyebrow":"Processing","heading":"Stone-ground, cold-pressed, sun-dried","body":"<p>Our flours are chakki-ground weekly, oils are wood-pressed at low temperatures and spices are sun-dried before grinding in small batches \\u2014 the slow methods that keep aroma, nutrients and character intact.<\\/p>","image":"https:\\/\\/images.unsplash.com\\/photo-1509358271058-acd22cc93898?w=1200&q=80&auto=format&fit=crop&h=900"},{"layout":"text-image","eyebrow":"Packaging","heading":"Packed the week it arrives","body":"<p>Nothing sits in a warehouse for months. Dry fruits are nitrogen-flushed, flours carry their milling date and every pack prints its harvest and origin.<\\/p>","image":"https:\\/\\/images.unsplash.com\\/photo-1532336414038-cf19250c5757?w=1200&q=80&auto=format&fit=crop&h=900"}],"values":[{"title":"Traceable to the farm","text":"Harvest, origin and lot number on every pack."},{"title":"Fair to farmers","text":"Prices agreed before sowing, paid within seven days of delivery."},{"title":"Nothing artificial","text":"No colours, preservatives, refined additives or fillers."},{"title":"Lab-tested","text":"Every lot tested for residues and adulteration."}],"sustainability_heading":"Better for the soil, too.","sustainability_body":"<p>Sixty percent of our partner farms are certified organic and the rest are in conversion. We fund natural farming training, buy the rain-fed millets that keep dryland farms viable, and ship in paper and reusable tins wherever we can.<\\/p>","sustainability_image":"https:\\/\\/images.unsplash.com\\/photo-1536304993881-ff6e9eefa2a6?w=1200&q=80&auto=format&fit=crop&h=900","founder_quote":"A good pantry is not about more choice. It is about knowing exactly where each ingredient came from.","founder_name":"Ananya Rao, founder"}', 'heritage');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (30, 'We would love to hear from you.', 'contact', 'contact', 'Contact', 'Questions about an order, a product or a bulk requirement — we reply within one business day.', NULL, NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:45', '2026-09-18 06:49:45', '{"subjects":["Order enquiry","Product question","Bulk \\/ corporate gifting","Returns & refunds","Farmer partnership","Other"]}', 'heritage');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (31, 'Frequently asked questions', 'faq', 'faq', 'Help', 'Ordering, delivery, freshness, certifications and returns — answered.', NULL, NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:45', '2026-09-18 06:49:45', NULL, 'heritage');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (32, 'Shipping & delivery', 'shipping', 'legal', NULL, 'Pan-India delivery, timelines and charges.', '<h3>Coverage</h3><p>We deliver to over 19,000 pincodes across India through our courier partners. Enter your pincode at checkout to see the estimated delivery date.</p><h3>Timelines</h3><p>Metro cities: 2–3 business days. Rest of India: 3–5 business days. Orders placed before 2 pm ship the same day, Monday to Saturday.</p><h3>Charges</h3><p>Free delivery on orders above ₹999. A flat charge, shown at checkout, applies to smaller orders.</p><h3>Packaging</h3><p>Dry fruits are nitrogen-flushed, oils and ghee ship in leak-proof jars with protective wrap, and flours are packed in kraft-paper pouches.</p>', NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:45', '2026-09-18 06:49:45', NULL, 'heritage');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (33, 'Returns & refunds', 'returns', 'legal', NULL, 'Our quality promise.', '<h3>Quality promise</h3><p>If any product arrives damaged, leaking, expired or not as described, tell us within 7 days of delivery with a photo and we will replace it or refund it in full.</p><h3>What we cannot take back</h3><p>Opened food products cannot be returned for hygiene reasons unless they are defective. Gift boxes may be returned unopened within 7 days.</p><h3>Refunds</h3><p>Refunds are issued to the original payment method within 5–7 business days. Cash-on-delivery orders are refunded by bank transfer.</p>', NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:45', '2026-09-18 06:49:45', NULL, 'heritage');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (34, 'Privacy policy', 'privacy', 'legal', NULL, NULL, '<h3>What we collect</h3><p>Name, contact details, delivery addresses, order history and, with your consent, browsing preferences that help us recommend products.</p><h3>How we use it</h3><p>To fulfil orders, provide support, improve the store and — if you opt in — send offers and recipes. We never sell personal data.</p><h3>Sharing</h3><p>Couriers receive your name, address and phone number to deliver your order. Payments are handled by PCI-DSS certified gateways; we do not store card details.</p><h3>Your rights</h3><p>Access, correct or delete your data from your account or by writing to us.</p>', NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:45', '2026-09-18 06:49:45', NULL, 'heritage');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (35, 'Terms & conditions', 'terms', 'legal', NULL, NULL, '<h3>Orders and pricing</h3><p>All prices are in Indian rupees and include GST. An order is confirmed when you receive the confirmation email; we may cancel and refund an order if a product becomes unavailable.</p><h3>Natural variation</h3><p>Our products are natural and minimally processed. Colour, grain size and crystallisation (in honey and ghee) vary between batches and seasons.</p><h3>Delivery</h3><p>Delivery timelines are estimates. Please inspect the parcel on arrival and report damage within 7 days.</p><h3>Accounts</h3><p>You are responsible for keeping your login details secure. We may suspend accounts that abuse offers.</p>', NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:45', '2026-09-18 06:49:45', NULL, 'heritage');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (36, 'Cookie policy', 'cookies', 'cookies', NULL, 'What cookies we use and how to control them.', '<h3>Essential</h3><p>Cart, login session and your saved preferences.</p><h3>Analytics</h3><p>Anonymous statistics that show us which pages and products help customers.</p><h3>Marketing</h3><p>Personalised offers and recipes. Optional — manage them from the panel on this page.</p>', NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:45', '2026-09-18 06:49:45', NULL, 'heritage');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (37, 'Payment options', 'payment', 'legal', NULL, 'Accepted methods and security.', '<h3>Accepted methods</h3><ul><li>UPI — Google Pay, PhonePe, Paytm and any UPI app</li><li>Credit and debit cards — Visa, Mastercard, RuPay, American Express</li><li>Net banking from all major Indian banks</li><li>Wallets — Paytm, Amazon Pay</li><li>Cash on delivery</li></ul><h3>Security</h3><p>Payments are processed by PCI-DSS Level 1 certified partners over encrypted connections. We never see or store your card number.</p>', NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:45', '2026-09-18 06:49:45', NULL, 'heritage');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (38, 'Give the gift of a good pantry.', 'gift-cards', 'gift-cards', 'Gift cards', 'Digital gift cards delivered by email — for housewarmings, weddings and festivals.', NULL, 'https://images.unsplash.com/photo-1512909006721-3d6018887383?w=1600&q=80&auto=format&fit=crop&h=800', 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:45', '2026-09-18 06:49:45', '{"steps":[{"title":"Choose an amount","text":"From \\u20b9500 to \\u20b910,000."},{"title":"Add a message","text":"We design the card around your note."},{"title":"Delivered by email","text":"Instantly, or on a date you choose."}]}', 'heritage');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (39, 'Work with us.', 'careers', 'careers', 'Careers', 'Sourcing, quality, operations and technology — join a team that visits the farms it buys from.', NULL, 'https://images.unsplash.com/photo-1464226184884-fa280b87c399?w=1600&q=80&auto=format&fit=crop&h=800', 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:45', '2026-09-18 06:49:45', '{"roles":[{"title":"Sourcing Manager \\u2014 Spices","location":"Kochi","type":"Full-time","summary":"Build relationships with spice-growing collectives in Kerala and Karnataka; own quality from harvest to pack."},{"title":"Quality Analyst","location":"Bengaluru","type":"Full-time","summary":"Run our lab-testing programme and the batch traceability system."},{"title":"Customer Care Associate","location":"Remote (India)","type":"Full-time","summary":"Help customers with orders, recipes and product questions across chat, phone and email."}],"perks":["Monthly pantry allowance","Farm visits with the sourcing team","Health insurance for you and family","Flexible working for office roles"]}', 'heritage');
INSERT INTO `pages` (`id`, `title`, `slug`, `template`, `eyebrow`, `excerpt`, `body`, `image`, `is_active`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `data`, `storefront_template`) VALUES (40, 'Our stores', 'stores', 'stores', 'Visit us', 'Taste before you buy, pick up online orders and meet the team.', NULL, NULL, 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:45', '2026-09-18 06:49:45', NULL, 'heritage');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (1, 'The Art of Dressing', 'the-art-of-dressing', 'Editorial', 'On proportion, restraint and the quiet confidence of a wardrobe that knows exactly what it is.', '<p>On proportion, restraint and the quiet confidence of a wardrobe that knows exactly what it is.</p><p>Full story coming soon.</p>', 'https://images.unsplash.com/photo-1571513722275-4b41940f54b8?w=1200&q=80&auto=format&fit=crop&h=1500', '6 min read', '2026-09-02 10:00:00', 1, NULL, NULL, NULL, NULL, 0, '2026-09-16 04:51:11', '2026-09-16 04:51:11', 'fashion');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (2, 'Modern Essentials', 'modern-essentials', 'Style Notes', 'Twelve pieces, endlessly combined. A closer look at the foundation of the Élan wardrobe.', '<p>Twelve pieces, endlessly combined. A closer look at the foundation of the Élan wardrobe.</p><p>Full story coming soon.</p>', 'https://images.unsplash.com/photo-1558769132-cb1aea458c5e?w=1200&q=80&auto=format&fit=crop&h=1500', '4 min read', '2026-08-20 10:00:00', 0, NULL, NULL, NULL, NULL, 0, '2026-09-16 04:51:11', '2026-09-16 04:51:11', 'fashion');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (3, 'The Signature Collection', 'the-signature-collection', 'Campaign', 'Behind the lens of our Autumn campaign — shot over three days in a converted textile mill.', '<p>Behind the lens of our Autumn campaign — shot over three days in a converted textile mill.</p><p>Full story coming soon.</p>', 'https://images.unsplash.com/photo-1524504388940-b1c1722653e1?w=1200&q=80&auto=format&fit=crop&h=1500', '8 min read', '2026-08-12 10:00:00', 0, NULL, NULL, NULL, NULL, 0, '2026-09-16 04:51:11', '2026-09-16 04:51:11', 'fashion');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (4, '15-minute paneer bhurji', '15-minute-paneer-bhurji', 'Recipes', 'A weeknight classic: crumbled paneer, onions, tomatoes and a handful of masalas. Ready before the rotis are.', '<h2>Ingredients</h2><ul><li>200 g paneer, crumbled</li><li>1 onion, 2 tomatoes, finely chopped</li><li>1 green chilli, ½ tsp turmeric, 1 tsp garam masala</li><li>Coriander, salt, 1 tbsp oil</li></ul><h2>Method</h2><ol><li>Heat oil, soften the onion and chilli.</li><li>Add tomatoes and spices; cook until the oil separates.</li><li>Fold in the paneer, cook 3 minutes, finish with coriander.</li></ol>', 'https://images.unsplash.com/photo-1631452180519-c014fe946bc7?w=1400&q=80&auto=format&fit=crop&h=900', '3', '2026-09-17 06:31:49', 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:31:49', '2026-09-18 06:31:49', 'grocery');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (5, 'How to keep fruits and vegetables fresh for longer', 'how-to-store-fruits-and-vegetables', 'Tips', 'Which ones go in the fridge, which stay out, and why bananas should live alone.', '<p>Leafy greens: wash, dry, wrap in a kitchen towel and refrigerate. Tomatoes and bananas: room temperature, away from other fruit — they release ethylene that ripens everything nearby. Potatoes and onions: cool, dark and separate. Berries: unwashed in the fridge; rinse just before eating.</p>', 'https://images.unsplash.com/photo-1610348725531-843dff563e2c?w=1400&q=80&auto=format&fit=crop&h=900', '4', '2026-09-08 06:31:49', 0, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:31:49', '2026-09-18 06:31:49', 'grocery');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (6, 'A week of meals under ₹999', 'weekly-meal-prep-under-999', 'Budget', 'Dal, rice, two sabzis, eggs and fruit — a realistic plan for two people, with the shopping list.', '<h2>The list</h2><ul><li>Toor dal 1 kg, basmati rice 2 kg, atta 2 kg</li><li>Onions, tomatoes, potatoes, spinach, carrots</li><li>12 eggs, 1 L milk, 200 g paneer</li><li>Bananas and apples for breakfast</li></ul><p>Cook dal and rice in bulk on Sunday; rotate sabzis through the week; keep eggs for quick dinners.</p>', 'https://images.unsplash.com/photo-1547592180-85f173990554?w=1400&q=80&auto=format&fit=crop&h=900', '5', '2026-09-17 06:31:49', 0, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:31:49', '2026-09-18 06:31:49', 'grocery');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (7, 'How to cook perfect basmati, every time', 'perfect-basmati-every-time', 'Kitchen notes', 'Rinse, soak, ratio, rest — the four steps that turn aged basmati into long, separate, fragrant grains.', '<h2>1. Rinse</h2><p>Wash the rice in cold water until it runs clear — this removes surface starch that makes grains stick.</p><h2>2. Soak</h2><p>Twenty minutes in cold water lets the grains hydrate evenly and lengthen fully.</p><h2>3. Ratio</h2><p>1 cup rice to 1.5 cups water for the absorption method; a pinch of salt and a teaspoon of ghee.</p><h2>4. Rest</h2><p>Once the water is absorbed, take it off the heat and leave it covered for 10 minutes. Fluff with a fork, never a spoon.</p>', 'https://images.unsplash.com/photo-1536304993881-ff6e9eefa2a6?w=1400&q=80&auto=format&fit=crop&h=900', '4', '2026-08-20 07:53:07', 1, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:45', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (8, 'Why bilona ghee tastes different', 'why-bilona-ghee-is-different', 'Stories', 'Thirty litres of milk, a day of culturing, and a wooden churn: the slow method behind our A2 ghee.', '<p>Most commercial ghee is made by boiling cream. Bilona ghee starts with milk that is cultured into curd overnight, churned with a wooden bilona to separate the butter, and only then slowly simmered. It takes 30 litres of A2 milk to make one kilo — which is why it is granular, nutty and fragrant in a way boiled-cream ghee never is.</p>', 'https://images.unsplash.com/photo-1589985270826-4b7bb135bc9d?w=1400&q=80&auto=format&fit=crop&h=900', '5', '2026-09-16 07:53:07', 0, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:45', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (9, 'Building the everyday masala dabba', 'the-everyday-masala-dabba', 'Kitchen notes', 'Seven spices that cook ninety percent of Indian home food — and how to keep them fresh.', '<p>Turmeric, red chilli, coriander, cumin, mustard seeds, garam masala and asafoetida. Buy whole where you can, grind in small batches, and keep the dabba away from the stove — heat and light are the enemies of aroma.</p>', 'https://images.unsplash.com/photo-1506368249639-73a05d6f6488?w=1400&q=80&auto=format&fit=crop&h=900', '3', '2026-09-12 07:53:07', 0, NULL, NULL, NULL, NULL, 0, '2026-09-18 06:49:45', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (10, 'Millets, back on the Indian plate', 'millets-back-on-the-plate', 'Wellness', 'Foxtail, little, barnyard, ragi — how to swap one meal a day to millets without anyone at the table noticing.', '<p>Millets were the everyday grain of most of India until polished rice and wheat took over. They are low-GI, high in fibre and grow on rain alone. Start with ragi dosa or foxtail upma — both taste familiar — and move to millet khichdi and pulao once the family is used to the nutty flavour.</p>', 'https://images.unsplash.com/photo-1574323347407-f5e1ad6d020b?w=1400&q=80&auto=format&fit=crop&h=900', '4', '2026-08-25 07:53:07', 0, NULL, NULL, NULL, NULL, 0, '2026-09-18 07:53:07', '2026-09-18 07:53:07', 'heritage');
INSERT INTO `posts` (`id`, `title`, `slug`, `category`, `excerpt`, `body`, `image`, `read_time`, `published_at`, `is_featured`, `meta_title`, `meta_description`, `og_image`, `canonical_url`, `noindex`, `created_at`, `updated_at`, `template`) VALUES (11, 'Why raw honey crystallises (and why that is good)', 'raw-honey-crystallises', 'Stories', 'Crystallised honey is not spoilt honey. It is the surest sign that nothing was heated, filtered or added.', '<p>Raw honey is a supersaturated sugar solution with pollen and wax particles in it. In winter the glucose settles around those particles and the jar turns creamy and opaque. Stand the jar in warm water for ten minutes to loosen it — never microwave it, which destroys the enzymes you paid for.</p>', 'https://images.unsplash.com/photo-1471943311424-646960669fbc?w=1400&q=80&auto=format&fit=crop&h=900', '3', '2026-08-28 07:53:07', 0, NULL, NULL, NULL, NULL, 0, '2026-09-18 07:53:07', '2026-09-18 07:53:07', 'heritage');
