INSERT INTO `settings` (`key`, `value`, `created_at`, `updated_at`) VALUES ('site', '{"name":"Maison \\u00c9lan","logo_primary":"MAISON","logo_accent":"\\u00c9lan","tagline":"Luxury fashion & lifestyle","description":"Maison \\u00c9lan \\u2014 an edit of clothing, fragrance, timepieces, leather goods and accessories designed for the moments that define you.","announcement_text":"Complimentary shipping on orders over \\u20b915,000","announcement_text_short":"Free shipping over \\u20b915,000","announcement_link_label":"Discover the New Season","announcement_link_url":"\\/collections\\/new-season","free_shipping_threshold":15000,"contact_email":"care@maisonelan.com","contact_phone":"+91 80 4500 1200","contact_hours":"Mon \\u2013 Sat, 10:00 \\u2013 19:00 IST","social_instagram":"https:\\/\\/instagram.com","social_pinterest":"https:\\/\\/pinterest.com","social_facebook":"https:\\/\\/facebook.com","social_youtube":"https:\\/\\/youtube.com","payment_methods":["Visa","Mastercard","Amex","UPI","RuPay","PayPal","Apple Pay","G Pay"],"footer_blurb":"Clothing, fragrance, timepieces and leather goods designed with intention and made to last beyond the season.","footer_newsletter_heading":"Early access, private sales and notes from the atelier.","page_header_image":"https:\\/\\/images.unsplash.com\\/photo-1558769132-cb1aea458c5e?w=2000&q=80&auto=format&fit=crop&h=900","admin_login_style":"classic"}', '2026-09-16 04:51:12', '2026-09-18 10:00:55');
INSERT INTO `settings` (`key`, `value`, `created_at`, `updated_at`) VALUES ('seo', '{"default_title":"Maison \\u00c9lan \\u2014 Luxury fashion & lifestyle","title_suffix":" \\u2014 Maison \\u00c9lan","default_description":"Clothing, fragrance, timepieces, leather goods and accessories designed for the moments that define you.","default_og_image":"https:\\/\\/images.unsplash.com\\/photo-1524504388940-b1c1722653e1?w=1200&q=80&auto=format&fit=crop&h=630","google_site_verification":null,"gtag_id":null,"robots_extra":null,"discourage_indexing":true}', '2026-09-16 04:51:12', '2026-09-17 06:26:13');
INSERT INTO `settings` (`key`, `value`, `created_at`, `updated_at`) VALUES ('home', '{"hero_eyebrow":"Autumn \\/ Winter 2026 \\u2014 The New Season","hero_eyebrow_short":"AW 2026 \\u2014 New Season","hero_heading":"The quiet\\n*confidence* of\\ndressing well.","hero_text":"Clothing, fragrance, timepieces and leather goods designed with intention \\u2014 for the moments that define you.","hero_primary_label":"Shop Collection","hero_primary_url":"\\/collections\\/new-season","hero_secondary_label":"Explore New Arrivals","hero_secondary_url":"\\/shop\\/new-arrivals","hero_image":"https:\\/\\/images.unsplash.com\\/photo-1524504388940-b1c1722653e1?w=1600&q=80&auto=format&fit=crop&h=2000&crop=faces","hero_image_alt":"Autumn \\/ Winter campaign \\u2014 a model in a sheer black blouse against a charcoal backdrop","hero_caption":"Campaign 01 \\/ Shot in Marseille","hero_look_title":"Look 01","hero_look_text":"Sheer silk blouse \\u2014 Signature Collection","ticker_items":["Clothing","Perfumes","Watches","Bags","Belts","Accessories"],"categories_eyebrow":"Explore","categories_heading":"Six categories. One point of view.","categories_text":"From the wardrobe to the vanity to the wrist \\u2014 every piece carries the same restraint and attention to material.","arrivals_eyebrow":"Just in","arrivals_heading":"New Arrivals","arrivals_limit":8,"arrivals_text":"The latest additions to the edit \\u2014 arriving weekly, in limited quantities.","editorial_eyebrow":"The Season","editorial_heading":"Designed for the moments that *define* you.","editorial_text":"We begin every collection with a question: what will you reach for, again and again? The answer is rarely loud. It is the coat with the perfect drape, the scent that becomes yours, the watch that outlives trends. Pieces made carefully, in small runs, from materials chosen for how they age.","editorial_cta_label":"Discover the Collection","editorial_cta_url":"\\/collections\\/new-season","editorial_image":"https:\\/\\/images.unsplash.com\\/photo-1526413232644-8a40f03cc03b?w=1400&q=80&auto=format&fit=crop&h=1700","editorial_image_secondary":"https:\\/\\/images.unsplash.com\\/photo-1571513722275-4b41940f54b8?w=900&q=80&auto=format&fit=crop&h=1200","editorial_caption":"Campaign 02 \\u2014 Editorial","editorial_stats":[{"value":"48","label":"New pieces"},{"value":"6","label":"Categories"},{"value":"3","label":"Ateliers"}],"featured_collection_id":3,"featured_eyebrow":"The House Signature","featured_text_extra":"Cut in Italian wool, lined in silk, finished by hand.","featured_secondary_label":"Read the Story","featured_secondary_url":"\\/journal\\/the-signature-collection","bestsellers_eyebrow":"Most loved","bestsellers_heading":"Best Sellers","bestsellers_text":"The pieces our clients return to \\u2014 season after season.","fragrance_product_id":6,"fragrance_eyebrow":"Fragrance Spotlight","fragrance_heading":"Amber *Oud*","fragrance_subheading":"Eau de Parfum \\u00b7 50ml \\/ 100ml","fragrance_size":"100ml","fragrance_text":"A composition that unfolds slowly: a bright, peppered opening giving way to smoked oud and rose, resting on a base of amber and sandalwood that lingers well into the evening. Created in Grasse with master perfumer \\u00c9lodie Marchand.","fragrance_image":"https:\\/\\/images.unsplash.com\\/photo-1622618991746-fe6004db3a47?w=1600&q=80&auto=format&fit=crop&h=2000","fragrance_caption":"Fragrance \\u2014 N\\u00b0 01","fragrance_notes":[{"label":"Top","value":"Pink pepper, bergamot, saffron"},{"label":"Heart","value":"Smoked oud, Bulgarian rose"},{"label":"Base","value":"Amber, Siam benzoin, sandalwood"}],"journal_eyebrow":"The Journal","journal_heading":"Notes on style, craft and the season.","promises":[{"icon":"badge-check","title":"Authentic Products","text":"Every piece is sourced directly from our ateliers and partner houses. Guaranteed."},{"icon":"gem","title":"Premium Quality","text":"Natural fibres, full-grain leathers and Swiss movements \\u2014 chosen for how they age."},{"icon":"lock","title":"Secure Payments","text":"256-bit encrypted checkout with cards, UPI, wallets and cash on delivery."},{"icon":"truck","title":"Fast & Reliable Shipping","text":"Complimentary express delivery over \\u20b915,000, tracked from our door to yours."},{"icon":"rotate","title":"Easy Returns","text":"30 days to return or exchange, collected from your home at no charge."}],"newsletter_eyebrow":"Newsletter","newsletter_heading":"Enter the world of *Maison \\u00c9lan*","newsletter_text":"Early access to new collections, private sales and stories from the atelier \\u2014 a few times a season, never more."}', '2026-09-16 04:51:12', '2026-09-16 05:20:34');
