next order","newsletter_text":"Sign up for weekly deals and new arrivals. No spam, only savings."}', '2026-09-18 05:14:51', '2026-09-18 05:14:51');
INSERT INTO `settings` (`key`, `value`, `created_at`, `updated_at`) VALUES ('heritage_site', '{"logo_primary":"Annapurna","logo_accent":"Organics","logo_sub":"Organics","tagline":"Pure Indian pantry, delivered","promo_messages":["COD available","Free delivery across India on eligible orders","Festive Sale is live \\u2014 up to 30% off selected staples","Mystery gift on orders above \\u20b91,499"],"delivery_note":"Pan-India delivery in 2\\u20135 days","search_placeholder":"Search","search_suggestions":["Basmati rice","Toor dal","A2 ghee","Turmeric","Almonds","Masala chai"],"nav_featured_label":"Festive Special","nav_featured_url":"\\/collections\\/festive-cooking","nav_all_label":"All Products","nav_category_label":"Shop By Category","nav_need_label":"Shop By Need","support_phone":null,"support_toll_free":"1800-000-0000","support_hours":"10 AM \\u2013 7 PM (Monday to Saturday)","support_email":null,"gifting_email":null,"whatsapp_number":null,"footer_blurb":"Single-origin staples, stone-ground flours, cold-pressed oils and heirloom spices \\u2014 sourced directly from farmer collectives across India.","certifications":["FSSAI licensed","India Organic certified","No artificial preservatives"],"show_diet_filter":true}', '2026-09-18 07:25:49', '2026-09-18 07:38:02');
INSERT INTO `settings` (`key`, `value`, `created_at`, `updated_at`) VALUES ('heritage_home', '{"hero_slides":[{"eyebrow":"Harvest 2026","heading":"Pure ingredients. Timeless Indian taste.","text":"Heirloom grains, sun-dried spices and cold-pressed oils from farms we know by name.","cta_label":"","cta_url":"\\/shop","image":"https:\\/\\/images.unsplash.com\\/photo-1532336414038-cf19250c5757?w=1800&q=80&auto=format&fit=crop&h=800","badges":["Stone-ground & cold-pressed","Farmer-direct sourcing","Lab-tested batches","Nothing artificial"]},{"eyebrow":"Festive season","heading":"Ghee, dry fruits and sweets for the celebrations.","text":"Curated gift boxes and premium staples \\u2014 up to 30% off until Diwali.","cta_label":"","cta_url":"\\/shop\\/sale","image":"https:\\/\\/images.unsplash.com\\/photo-1512909006721-3d6018887383?w=1800&q=80&auto=format&fit=crop&h=800","badges":["Reusable gift tins","Hand-packed","Pan-India delivery","Custom notes"]},{"eyebrow":"From the fields","heading":"Single-origin rice, milled to order.","text":"Aged basmati, red rice and millets from cooperative farms in Punjab, Kerala and Karnataka.","cta_label":"","cta_url":"\\/shop\\/rice-grains","image":"https:\\/\\/images.unsplash.com\\/photo-1536304993881-ff6e9eefa2a6?w=1800&q=80&auto=format&fit=crop&h=800","badges":["Aged 24 months","Milled weekly","Single origin","Low GI options"]}],"sections":[{"key":"strip","enabled":true},{"key":"featured","enabled":true},{"key":"combos","enabled":true},{"key":"bestsellers","enabled":true},{"key":"video","enabled":true},{"key":"needs","enabled":true},{"key":"new","enabled":true},{"key":"certifications","enabled":true},{"key":"trust","enabled":true},{"key":"categories","enabled":true},{"key":"values","enabled":true},{"key":"offer","enabled":false},{"key":"journal","enabled":true},{"key":"testimonials","enabled":true}],"strip_text":"We stone-grind, cold-press and sun-dry \\u2014 never refine, bleach or polish \\u2014 so every pack keeps the whole grain\\u2019s goodness.","strip_image":"https:\\/\\/images.unsplash.com\\/photo-1506368249639-73a05d6f6488?w=1600&q=80&auto=format&fit=crop&h=300","featured_heading":"Festive Special","featured_source":"collection","featured_collection_slug":"festive-cooking","featured_limit":10,"combos_heading":"Super Saver Combos","combos_collection_slug":"everyday-essentials","combos_limit":10,"bestsellers_heading":"Our Best Sellers","bestsellers_limit":10,"video_url":null,"video_poster":"https:\\/\\/images.unsplash.com\\/photo-1556909212-d5b604d0c90d?w=1600&q=80&auto=format&fit=crop&h=800","needs_heading":"Shop By Need","needs_limit":8,"new_heading":"New Arrivals","new_limit":10,"certifications_heading":"Our Certifications","certifications":[{"label":"FSSAI Licensed"},{"label":"India Organic"},{"label":"NPOP Certified"},{"label":"Jaivik Bharat"},{"label":"ISO 22000"},{"label":"Non-GMO"},{"label":"Lab Tested"},{"label":"Fair Trade"}],"trust_heading":"Benefit From Choosing The Best","trust_image":"https:\\/\\/images.unsplash.com\\/photo-1464226184884-fa280b87c399?w=1000&q=80&auto=format&fit=crop&h=900","trust_items":[{"icon":"badge","title":"100% Quality Products","text":"Every batch lab-tested"},{"icon":"lock","title":"Secure Payments","text":"UPI, cards, wallets, COD"},{"icon":"truck","title":"Pan-India Delivery","text":"19,000+ pincodes"},{"icon":"rotate","title":"Easy Returns","text":"7-day quality promise"},{"icon":"leaf","title":"Trusted Ingredients","text":"Nothing artificial, ever"},{"icon":"star","title":"1,200+ Farmers","text":"Paid above market rates"}],"categories_heading":"Our Range Of Categories","categories_limit":10,"offer_heading":"Conscious Gifting, Redefined","offer_text":"Festive hampers of dry fruits, ghee, spices and teas in reusable tins \\u2014 up to 30% off this season.","offer_cta_label":"Shop gift boxes","offer_cta_url":"\\/shop\\/gift-boxes","offer_image":"https:\\/\\/images.unsplash.com\\/photo-1512909006721-3d6018887383?w=1600&q=80&auto=format&fit=crop&h=800","offer_badge":"Up to 30% off","values_strip":[{"icon":"badge","label":"FSSAI-approved facilities"},{"icon":"diamond","label":"Made in India"},{"icon":"leaf","label":"Eco-friendly packaging"},{"icon":"shield","label":"Ethical sourcing"},{"icon":"star","label":"100% natural"},{"icon":"check","label":"Non-GMO & unrefined"}],"journal_heading":"Blogs","testimonials_heading":"500+ Happy Kitchens","testimonials_image":"https:\\/\\/images.unsplash.com\\/photo-1556910103-1c02745aae4d?w=800&q=80&auto=format&fit=crop&h=1000","testimonials":[{"name":"Meera","location":"Chennai","rating":5,"text":"The aged basmati is the best I have cooked with \\u2014 long, fragrant grains that never turn sticky.","product":"Aged Basmati Rice"},{"name":"Arjun","location":"Pune","rating":5,"text":"Finally an A2 ghee that tastes like the one from my grandmother\\u2019s village. Granular, nutty and honest.","product":"A2 Gir Cow Ghee"},{"name":"Farah","location":"Lucknow","rating":4,"text":"Spices arrived within three days and the garam masala is incredibly fresh \\u2014 you can smell the cardamom through the pack.","product":"Garam Masala"},{"name":"Siddharth","location":"Mumbai","rating":5,"text":"The atta makes soft rotis that stay soft till dinner. Milling date on the pack is a nice touch.","product":"Whole Wheat Atta"},{"name":"Priya","location":"Bengaluru","rating":5,"text":"Honey crystallised in winter and they had already explained why on the jar. Tastes like real forest honey.","product":"Raw Forest Honey"},{"name":"Nikhil","location":"Noida","rating":4,"text":"Packaging is clean, the dal cooks quickly and it is unpolished as promised. Will reorder.","product":"Toor Dal"}],"story_heading":"Our Farmers Are the Heart of Our Purpose","story_text":"Every grain, dal and spice comes from small farmer collectives across twelve Indian states. We agree prices above the mandi rate before sowing, pay within seven days of delivery and fund natural-farming training.\\n\\nWhen farmers thrive, the food on your table is better \\u2014 and so is the land it came from.","story_image":"https:\\/\\/images.unsplash.com\\/photo-1464226184884-fa280b87c399?w=1000&q=80&auto=format&fit=crop&h=1200","story_cta_label":"Learn more","story_cta_url":"\\/about","story_stats":[{"value":"1,200+","label":"Partner farmers"},{"value":"12","label":"Indian states"},{"value":"100%","label":"Lab-tested batches"},{"value":"10+","label":"Years of sourcing"}],"newsletter_heading":"Sign Up To Get Updates","newsletter_text":"Recipes, harvest news and \\u20b9100 off your first order."}', '2026-09-18 07:25:49', '2026-09-18 08:16:44');
